#!/usr/bin/env bash
# M20-T08 conformance of a WebAssembly backend (ADR-0061) on the running dev stack (profile wasm): every golden and
# conformance case is generated by codegen-<lang> /wasm, built in toolchain-wasm (wasi-sdk or cargo wasm32-wasip1)
# and its scenario run inside the guest by sv-wasm-host --test (writes, publishes, trace as the scenario expects).
#   modules/simvehicleapp-orchestrator/gate/m20-wasm-conformance.sh [cpp|rust]
set -euo pipefail
cd "$(dirname "$0")/../../.."
LANG_ID="${1:-cpp}"
INTERNAL_API_SECRET="${INTERNAL_API_SECRET:-$(sed -n 's/^INTERNAL_API_SECRET=//p' .env)}"
WORK=$(mktemp -d "${TMPDIR:-/tmp}/sv-wasm-conf-XXXXXX")
export INTERNAL_API_SECRET LANG_ID
docker run --rm --user "$(id -u):$(id -g)" --network simvehicleapp_sv-codegen -e INTERNAL_API_SECRET -e LANG_ID -e OUT=/out \
  -v "$PWD":/repo:ro -v "$WORK":/out -w /repo/modules/simvehicleapp-orchestrator oven/bun:1.3.8 bun gate/m20-wasm-conformance.ts
docker run --rm --user "$(id -u):$(id -g)" -e HOME=/tmp -e LANG_ID -v "$WORK":/w --entrypoint bash simvehicleapp/toolchain-wasm:dev -c '
  set -u; pass=0; fail=0; failed=""
  export CARGO_TARGET_DIR=/w/.target
  for d in /w/*/; do
    id=$(basename "$d"); p=/w/.proj-$id
    if [ "$LANG_ID" = rust ]; then cp -r "$SV_SEED_DIR_RUST/." "$p"; else cp -r "$SV_SEED_DIR_CPP/." "$p"; fi
    cp -r "$d/app/." "$p/app/"
    cd "$p"
    if [ "$LANG_ID" = rust ]; then
      ok=$(cargo build --manifest-path app/Cargo.toml --release --offline --target wasm32-wasip1 -j 2 -q 2>&1 && mkdir -p build && cp "$CARGO_TARGET_DIR/wasm32-wasip1/release/app.wasm" build/app.wasm && echo built)
    else
      ok=$(cmake -S app -B build/cmake -DCMAKE_TOOLCHAIN_FILE="$WASI_SDK_PATH/share/cmake/wasi-sdk-p1.cmake" -DCMAKE_BUILD_TYPE=Release >/dev/null 2>&1 && cmake --build build/cmake -j 2 >/dev/null 2>&1 && mkdir -p build && cp build/cmake/app.wasm build/app.wasm && echo built)
    fi
    if [ "$ok" != built ] || ! out=$(sv-wasm-host --test build/app.wasm app/tests/generated/cases.json 2>&1); then
      fail=$((fail+1)); failed="$failed $id"; echo "FAIL $id"; echo "${out:-build failed}" | grep -vE "^\[ (RUN|  OK|=)" | head -8
    else
      pass=$((pass+1))
    fi
  done
  echo "conformance ($LANG_ID-wasm, sv-wasm-host): $pass/$((pass+fail)) PASS${failed:+ — failed:$failed}"
  [ "$fail" -eq 0 ]'
